changes.before:
/*
 * DTF Prints prototype — layers on top of quick-quote.css (reuses its tokens:
 * --qq-green, --qq-ink, --qq-muted, --qq-line, --qq-card, --qq-bg, --qq-warn-*).
 * Only the prints-list rows + result breakdown are new here.
 */

/* Page theme (CSS standardization, 2026-09-07): this page's own colours, auto-named by hue so the page
   keeps its exact look. Map them to shared_components/css/tokens.css names when the page is redesigned;
   every rule below uses var(). Raw hex is allowed ONLY in this block. */
/* stylelint-disable color-no-hex */
:root {
    --dtf-prints-prototype-red: #b4421f;
    --dtf-prints-prototype-orange: #7a541a;
    --dtf-prints-prototype-orange-2: #8a5a14;
    --dtf-prints-prototype-red-2: #c0392b;
    --dtf-prints-prototype-red-3: #e7b7b1;
}
/* stylelint-enable color-no-hex */

.proto-banner {
    margin: 0 0 18px;
    padding: 10px 14px;
    background: var(--color-dash-theme-bg);
    border: 1px solid var(--qq-line);
    border-left: 3px solid var(--qq-green);
    border-radius: 9px;
    font-size: 13px;
    color: var(--store-ink-soft);
    line-height: 1.5;
}

/* ---- method toggle ---- */
.proto-method { display: inline-flex; gap: 0; border: 1px solid var(--qq-line); border-radius: 9px; overflow: hidden; }

.proto-method button {
    padding: 9px 22px; border: 0; background: var(--color-surface); cursor: pointer;
    font: inherit; font-weight: 600; font-size: 14px; color: var(--qq-muted);
    transition: background .12s, color .12s;
}
.proto-method button + button { border-left: 1px solid var(--qq-line); }
.proto-method button.is-active { background: var(--qq-green); color: var(--color-on-brand); }
.proto-method button:not(.is-active):hover { background: var(--color-dash-theme-bg); color: var(--qq-green-dark, var(--print-green)); }

/* ---- prints list ---- */
.proto-prints { margin-top: 18px; }
.proto-prints > label { display: block; font-weight: 600; font-size: 13px; margin-bottom: 8px; }
.proto-prints .muted { font-weight: 400; color: var(--qq-muted); }

.proto-print-row {
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 8px 0;
    border-bottom: 1px dashed var(--qq-line);
}

.proto-print-n {
    flex: 0 0 auto;
    width: 22px; height: 22px;
    display: inline-flex; align-items: center; justify-content: center;
    background: var(--qq-green); color: var(--color-on-brand);
    border-radius: 50%;
    font-size: 12px; font-weight: 600;
}
.proto-print-size { flex: 1 1 auto; min-width: 150px; padding: 7px 9px; font-size: 13px; }
.proto-logo-role { flex: 0 0 auto; font-size: 13px; font-weight: 500; color: var(--qq-ink, var(--print-ink)); min-width: 92px; }
.proto-logo-stitch { flex: 0 0 96px; width: 96px; padding: 7px 9px; font-size: 13px; font-family: "Geist Mono", monospace; text-align: right; }
.proto-logo-unit { flex: 0 0 auto; font-size: 12px; color: var(--qq-muted); }
.proto-embtype { display: inline-flex; }
.proto-embtype button { font-size: 12px; padding: 6px 14px; }
.proto-extsizes { margin-top: 6px; }
.proto-ext-note { font-size: 11.5px; color: var(--qq-muted); margin: 0 0 8px; }
.proto-ext-grid { display: flex; flex-wrap: wrap; gap: 10px; }
.proto-ext-cell { display: flex; flex-direction: column; gap: 3px; font-size: 12px; }
.proto-ext-lbl { color: var(--qq-ink, var(--print-ink)); font-weight: 500; }
.proto-ext-count { width: 62px; padding: 6px 8px; font-size: 13px; font-family: "Geist Mono", monospace; text-align: right; }
.proto-sizes-sec { margin-top: 10px; }
.proto-sizes-head { font-weight: 600; font-size: 12px; color: var(--qq-muted); margin-bottom: 4px; }
.proto-ext-warn { color: var(--dtf-prints-prototype-red); font-size: 11.5px; margin: 6px 0 0; }
.proto-inventory { margin-top: 8px; }
.proto-inv-note { font-size: 12px; color: var(--qq-muted); }
.proto-inv-err { color: var(--dtf-prints-prototype-red); }
.proto-inv-head { font-size: 12px; font-weight: 600; margin-bottom: 6px; }
.proto-inv-head .muted { font-weight: 400; color: var(--qq-muted); }
.proto-inv-grid { display: flex; flex-wrap: wrap; gap: 5px; }
.proto-inv-cell { display: inline-flex; flex-direction: column; align-items: center; min-width: 42px; padding: 4px 7px; border-radius: 6px; font-size: 11px; line-height: 1.35; }
.proto-inv-cell.good { background: var(--store-green-50); color: var(--print-green); }
.proto-inv-cell.low { background: var(--store-rush-soft); color: var(--dtf-prints-prototype-orange-2); }
.proto-inv-cell.out { background: var(--store-rush-soft); color: var(--dtf-prints-prototype-red); }
.proto-inv-sz { font-weight: 600; }
.proto-inv-qty { font-family: "Geist Mono", monospace; }
.proto-color-count { flex: 0 0 60px; width: 60px; padding: 7px 9px; font-size: 13px; font-family: "Geist Mono", monospace; text-align: right; }
.proto-flash { color: var(--qq-muted); font-size: 11px; font-weight: 400; }

.proto-print-cost {
    flex: 0 0 auto;
    min-width: 78px; text-align: right;
    font-family: "Geist Mono", monospace; font-size: 13px;
    color: var(--qq-ink, var(--print-ink));
}

.proto-print-x {
    flex: 0 0 auto;
    width: 26px; height: 26px;
    border: 1px solid var(--qq-line); background: var(--color-surface);
    border-radius: 7px; cursor: pointer;
    color: var(--qq-muted); font-size: 17px; line-height: 1;
    transition: background .12s, color .12s, border-color .12s;
}
.proto-print-x:hover { background: var(--red-50); color: var(--dtf-prints-prototype-red-2); border-color: var(--dtf-prints-prototype-red-3); }
.proto-empty { color: var(--qq-muted); font-size: 13px; padding: 8px 0; }

#addPrint { margin-top: 10px; }

/* ---- result ---- */
.proto-result { padding-top: 4px; }
.proto-muted { color: var(--qq-muted); font-size: 14px; }

.proto-headline {
    display: flex; align-items: baseline; justify-content: space-between;
    gap: 12px; flex-wrap: wrap;
    padding-bottom: 12px; margin-bottom: 12px;
    border-bottom: 1px solid var(--qq-line);
}
.proto-pp { font-size: 30px; font-weight: 700; color: var(--qq-ink, var(--print-ink)); letter-spacing: -.5px; }
.proto-pp .per { font-size: 15px; font-weight: 500; color: var(--qq-muted); margin-left: 2px; }
.proto-order { font-size: 14px; color: var(--qq-muted); font-family: "Geist Mono", monospace; }

.proto-bd { display: flex; flex-direction: column; gap: 5px; }
.proto-bd-row { display: flex; justify-content: space-between; gap: 12px; font-size: 13px; color: var(--qq-muted); }
.proto-bd-row span:last-child { font-family: "Geist Mono", monospace; color: var(--qq-ink, var(--print-ink)); white-space: nowrap; }
.proto-bd-row .proto-band { color: var(--qq-muted); font-size: 11px; font-family: "Geist Mono", monospace; }
.proto-ltm span:last-child { color: var(--dtf-prints-prototype-orange); }
.proto-bd-row.proto-sub { margin-top: 4px; padding-top: 7px; border-top: 1px solid var(--qq-line); }
.proto-bd-row.proto-rounding span:last-child { color: var(--dtf-prints-prototype-orange); }
.proto-bd-row.proto-total { margin-top: 4px; padding-top: 7px; border-top: 2px solid var(--qq-line); }
.proto-bd-row.proto-total span, .proto-bd-row.proto-total span:last-child { color: var(--qq-ink, var(--print-ink)); font-weight: 600; font-size: 13.5px; }

.proto-round { margin: 12px 0 0; font-size: 11.5px; color: var(--qq-muted); }

/* ---- price-break matrix ---- */
.proto-matrix-wrap { margin-top: 20px; }
.proto-matrix { background: var(--qq-card, var(--color-surface)); border: 1px solid var(--qq-line); border-radius: 12px; padding: 18px 20px; }
.proto-matrix-head { font-weight: 600; font-size: 14px; margin-bottom: 12px; }
.proto-matrix-head .muted { font-weight: 400; color: var(--qq-muted); }
.proto-mx-scroll { overflow-x: auto; }
.proto-mx-table { width: 100%; border-collapse: collapse; font-size: 13px; white-space: nowrap; }
.proto-mx-table th { text-align: right; padding: 7px 12px; color: var(--qq-muted); font-weight: 500; font-size: 12px; border-bottom: 1px solid var(--qq-line); }
.proto-mx-table th:first-child { text-align: left; }
.proto-mx-table td { text-align: right; padding: 9px 12px; font-family: "Geist Mono", monospace; color: var(--qq-muted); border-bottom: 1px solid var(--qq-line-2, var(--store-green-50)); }
.proto-mx-table td:first-child { text-align: left; font-family: inherit; font-weight: 600; color: var(--qq-ink, var(--print-ink)); }
.proto-mx-table tbody tr { cursor: pointer; transition: background .1s; }
.proto-mx-table tbody tr:hover { background: var(--gray-50); }
.proto-mx-table tr.is-current { background: var(--color-dash-theme-bg); }
.proto-mx-table tr.is-current td { color: var(--qq-ink, var(--print-ink)); }
.proto-mx-table tr.is-current td:first-child { color: var(--qq-green); }
/* stylelint-disable-next-line declaration-no-important -- legacy: outranks a higher-specificity rule — re-examine when this page is redesigned */
.proto-mx-pp { font-weight: 600; color: var(--qq-ink, var(--print-ink)) !important; }
.proto-mx-note { margin: 12px 0 0; font-size: 11.5px; color: var(--qq-muted); }

/* ---- rate-card download button ---- */
.proto-ratecard-bar { margin-top: 14px; display: flex; align-items: center; gap: 12px; flex-wrap: wrap; }
.proto-rc-btn { display: inline-flex; align-items: center; gap: 7px; padding: 9px 14px; background: var(--qq-card, var(--color-surface)); border: 1px solid var(--qq-line); border-radius: 9px; font: 500 13px/1 Geist, sans-serif; color: var(--qq-ink, var(--print-ink)); cursor: pointer; transition: background .12s, border-color .12s, color .12s; }
.proto-rc-btn:hover { background: var(--color-dash-theme-bg); border-color: var(--qq-green); }
.proto-rc-btn:disabled { opacity: .6; cursor: default; }
.proto-rc-hint { font-size: 12px; color: var(--qq-muted); }

/* ---- rate-card print sheet (hidden on screen, shown only when printing) ---- */
#rateCardSheet { display: none; }
.rc-head { display: flex; align-items: center; gap: 14px; border-bottom: 2px solid var(--print-ink); padding-bottom: 10px; margin-bottom: 16px; }
.rc-logo { height: 34px; }
.rc-title { font: 700 18px Geist, sans-serif; }
.rc-meta { font-size: 12px; color: var(--print-ink-soft); font-family: "Geist Mono", monospace; margin-top: 2px; }
.rc-table { width: 100%; border-collapse: collapse; font-size: 12.5px; margin-bottom: 18px; }
.rc-table th { text-align: right; padding: 7px 10px; border-bottom: 1.5px solid var(--print-ink); font: 600 12px Geist, sans-serif; }
.rc-table th:first-child { text-align: left; font-size: 13px; }
.rc-table td { text-align: right; padding: 6px 10px; font-family: "Geist Mono", monospace; border-bottom: 1px solid var(--gray-200); }
.rc-table td:first-child { text-align: left; font-family: Geist, sans-serif; }
.rc-table .rc-blank td { font-weight: 600; }
.rc-table .rc-ltm td { color: var(--dtf-prints-prototype-orange); }
.rc-band { color: var(--print-line); font-size: 10.5px; font-family: "Geist Mono", monospace; }
.rc-howto { font-size: 11.5px; color: var(--gray-700); line-height: 1.5; border-top: 1px solid var(--gray-200); padding-top: 10px; }

@media print {
    /* stylelint-disable-next-line declaration-no-important -- legacy: outranks a higher-specificity rule — re-examine when this page is redesigned */
    .topbar, .hero, .proto-banner, #protoError, .qq-grid, .proto-matrix-wrap, .proto-ratecard-bar { display: none !important; }
    #rateCardSheet { display: block; }
    body { background: var(--color-surface); }

    @page { margin: 0.5in; }
}

